const clientStages=[['reference','received'],['proposal','recommendation'],['roadmap','choose'],['review','review'],['payment','activate'],['requirements','requirements'],['progress','delivery']];
let packageLevel=0,dependencyPrompt=null;
if(!db.clientStepOne){let base=lead('HH-JOURNEY-001')||db.leads[0],l=structuredClone(base);Object.assign(l,{id:'HH-FLOW-001',name:'sample interior design studio',paid:false,stage:'roadmap',payment:null,clientSelected:[],itemChoices:{},work:[],requirements:[],files:[],updates:[],events:[],activeSelection:[],quoteAccepted:false,next:'review your recommendation and choose a practical starting point',step1Demo:true});let ids=['item-0','item-1','item-3','item-4','item-5','item-6','item-7','s2','m2','s3'];let prices=[50000,30000,5000,5000,25000,60000,20000,150000,80000,180000];let services=ids.map((id,i)=>{let s=structuredClone(db.services.find(s=>s.id===id));if(!s)return null;s.price=prices[i];s.days=[7,5,2,2,3,7,5,10,7,14][i];s.code='HH-'+String(i+1).padStart(3,'0');s.dependencies=id==='s2'?['item-5','item-6']:[];s.dependencyReason=id==='s2'?'this sample website scope uses the approved business profile and brand assets. these can be supplied if you already have them.':'';return s}).filter(Boolean);l.roadmapVersion={services,version:1,at:now()};l.proposalVersion={text:'your next step is a clear foundation for attracting and handling suitable enquiries. check the documents and brand assets you already have, choose the missing essentials, then strengthen your portfolio and customer follow-up. start at a pace that suits you.',at:now(),version:1};l.proposal=l.proposalVersion.text;db.leads.push(l);db.clientStepOne=true;save()}
function flowItems(l){return l.roadmapVersion?.services||[]}
function choice(l,id){return l.itemChoices?.[id]||((l.clientSelected||[]).includes(id)?'selected':'later')}
function chosen(l){return flowItems(l).filter(s=>(l.clientSelected||[]).includes(s.id))}
function price(s,l){return s.price!==''?'₦'+Number(s.price).toLocaleString():'price to confirm'}
function duration(s){return s.days?`${s.days} working day${Number(s.days)===1?'':'s'}`:'timing to confirm'}
function quoteTotal(l){let list=chosen(l);return list.length&&list.every(s=>s.price!=='')?'₦'+list.reduce((n,s)=>n+Number(s.price),0).toLocaleString():'quotation required'}
function flowGo(l,stage){go('client/'+l.id+'/'+stage)}
function flowDone(l,key){return ({reference:!!l.answers,proposal:isPublished(l),roadmap:chosen(l).length>0||l.paid,review:!!l.quoteAccepted,payment:!!l.paid,requirements:l.requirements.length>0&&l.requirements.every(r=>['submitted','accepted'].includes(r.status)),progress:l.work.length>0&&l.work.every(w=>w.status==='delivered')})[key]}
function sampleBusinessDate(days){let d=new Date();while(days>0){d.setDate(d.getDate()+1);if(![0,6].includes(d.getDay()))days--}return d.toISOString()}
function flowHeader(l,current){let idx=clientStages.findIndex(x=>x[0]===current),n=Math.max(idx,0);return `<div class="flow-shell"><header class="flow-top"><a href="#home"><img src="assets/${brandFor()?brandFor().name==='hamzury hub'?'hub':brandFor().name:'hamzury'}.png" alt="hamzury" class="logo"></a><a href="https://desk.hamzury.com" target="_blank" rel="noopener">need help?</a></header><section class="flow-heading"><div><span class="eyebrow">your business journey</span><p class="flow-ref">${E(l.id)}</p></div><span class="flow-stepcount">step ${n+1} of ${clientStages.length}</span></section><nav class="flow-stages" aria-label="your journey stages">${clientStages.map(([key,label],i)=>`<div aria-label="${E(label)}: ${flowDone(l,key)?'complete':i===n?'current':'pending'}" class="flow-stage ${flowDone(l,key)?'complete':''} ${i===n?'current':''}" ${i===n?'aria-current="step"':''}><span>${flowDone(l,key)?'✓':String(i+1).padStart(2,'0')}</span><small>${label}</small></div>`).join('')}</nav><div class="flow-current-label">${E(clientStages[n][1])}${clientStages[n+1]?' <span>· next: '+E(clientStages[n+1][1])+'</span>':''}</div><div class="flow-track"><i style="width:${clientStages.filter(([key])=>flowDone(l,key)).length/clientStages.length*100}%"></i></div>${l.step1Demo?'<div class="flow-demo">sample journey · all prices, dates and payment states are illustrative</div>':''}`}
function flowEnd(l){return `<footer class="flow-footer">awareness / strategy / structure / systems / success<br><a href="#access">return with your reference</a> · <a href="https://desk.hamzury.com" target="_blank" rel="noopener">contact the desk</a></footer></div>${dependencyPrompt?.client===l.id?dependencyDialog(l):''}`}
function flowTitle(k,t,p){return `<div class="flow-title"><div class="eyebrow">${k}</div><h1>${t}</h1><p>${p}</p></div>`}
function referenceCard(l){return `<article class="reference-card"><div class="reference-brand">hamzury holding<span>your journey. a clear next step.</span></div><div class="reference-symbol">✓</div><h2>you’ve taken<br>the first step.</h2><p>thank you for choosing hamzury. we have received your answers. our specialist team will review your situation and prepare a clear recommendation.</p><div class="reference-code"><span>your journey reference</span><strong>${E(l.id)}</strong><small>keep this reference for your next visit.</small></div><div class="reference-footer">awareness → strategy → structure → systems → success</div></article>`}
function isPublished(l){return l.proposalVersion&&!l.proposalVersion.preliminary}
function missingDependencies(l){return chosen(l).flatMap(s=>(s.dependencies||[]).filter(id=>!['selected','have'].includes(choice(l,id))).map(id=>({service:s,required:flowItems(l).find(x=>x.id===id)})))}
const priorClientFlow=clientView;
clientView=function(){let l=lead(route[1]);if(!l)return notFound();let p=route[2]||'reference';if(p==='status')p=l.paid?'progress':isPublished(l)?'proposal':'reference';if(!clientStages.some(([s])=>s===p))p='reference';if(['requirements','progress'].includes(p)&&!l.paid){return flowHeader(l,'payment')+flowTitle('activation first','your work is not active yet.','review your selected services and payment status before completing requirements.')+`<div class="flow-actions">${button('review my selection →','client/'+l.id+'/review')}${button('back to roadmap','client/'+l.id+'/roadmap','secondary')}</div>`+flowEnd(l)}let h=flowHeader(l,p);
if(p==='reference')return h+flowTitle('awareness / received','your next step starts here.','save your reference card. your reviewed recommendation will appear in this same journey.')+referenceCard(l)+`<div class="flow-actions"><button onclick="saveReference('${l.id}')">save my reference card</button>${isPublished(l)?button('my recommendation is ready →','client/'+l.id+'/proposal','secondary'):'<span class="flow-wait">◷ awaiting team review</span>'}</div><div class="flow-note">your reference card contains no private answers. it identifies your journey; verified access will protect the live client account.</div>`+flowEnd(l);
if(p==='proposal')return h+flowTitle('strategy / your recommendation','a practical place to begin.',E(l.name))+`<article class="flow-message"><span class="eyebrow">a message from hamzury</span><p>${E(isPublished(l)?l.proposalVersion.text:'thank you for sharing your situation. our team will review your answers and prepare a recommendation. there is nothing to purchase at this stage.')}</p><div class="flow-next"><span>your next action</span><strong>${isPublished(l)?'check what you already have, then choose the missing essentials.':'keep your reference and return when your review is ready.'}</strong></div></article><div class="flow-actions">${isPublished(l)&&l.roadmapVersion?button('open my roadmap →','client/'+l.id+'/roadmap'):button('back to my reference','client/'+l.id+'/reference')}<button class="ghost" onclick="saveReference('${l.id}')">save my reference</button></div>`+flowEnd(l);
if(p==='roadmap'){let all=flowItems(l),list=all.filter(s=>s.level===packageLevel);return h+flowTitle('structure / choose your starting point','only the work you need.','add an item, mark it already available, or leave it for later. tap the name for details.')+`<div class="flow-packages" role="tablist" aria-label="roadmap stages">${['minimum','standard','premium','scale & growth'].map((s,i)=>`<button role="tab" aria-selected="${packageLevel===i}" class="${packageLevel===i?'active':''}" onclick="packageLevel=${i};render()">${s}</button>`).join('')}</div><div class="flow-stageintro"><h2>${['minimum','standard','premium','scale & growth'][packageLevel]}</h2><p>${['the missing essentials for a more prepared business.','present your work and handle enquiries consistently.','connect the work and strengthen delivery.','prepare for your next stage of growth.'][packageLevel]}</p></div><div class="flow-items">${list.map(s=>flowItem(l,s)).join('')||'<div class="flow-note">no services recommended in this stage yet. your team can add the relevant next step.</div>'}</div><div class="flow-bottom"><div><strong>${chosen(l).length} selected</strong><span>${chosen(l).length?quoteTotal(l):'choose a useful starting point'}</span></div><button onclick="reviewFlow('${l.id}')" ${chosen(l).length?'':'disabled'}>review selection →</button></div>`+flowEnd(l)}
if(p==='review'){let mis=missingDependencies(l);return h+flowTitle('strategy / review your selection','comfortable with your choices?','keep the useful items. remove anything you want to postpone, then review the total.')+`<section class="flow-review">${chosen(l).map(s=>`<div class="flow-reviewrow"><div>${tag(s.v)}<h3>${E(s.title)}</h3><span class="small">${duration(s)}</span></div><div><strong>${price(s,l)}</strong><button class="ghost" onclick="requestFlowChoice('${l.id}','${s.id}','later')">remove</button></div></div>`).join('')||'<p class="flow-note">your selection is empty. return to the roadmap to choose your starting point.</p>'}<div class="flow-total"><span>selected total</span><strong>${quoteTotal(l)}</strong></div><p class="small">${l.step1Demo?'sample prices for testing the experience. no live order or charge.':'final scope, terms and applicable external fees must be confirmed in your quotation.'}</p></section>${mis.length?`<div class="flow-notice danger"><b>your selection needs a check</b>${mis.map(x=>`<p>${E(x.service.title)} needs ${E(x.required?.title||'an existing asset')}.</p>`).join('')}</div>`:''}<div class="flow-actions"><button onclick="acceptFlowQuote('${l.id}')" ${!chosen(l).length||mis.length?'disabled':''}>confirm selection & continue →</button>${button('adjust my roadmap','client/'+l.id+'/roadmap','secondary')}</div>`+flowEnd(l)}
if(p==='payment')return h+flowTitle('systems / activation','one final check before work begins.','your payment status and your next action stay visible here.')+`<section class="flow-message"><div class="flow-total"><span>selected scope</span><strong>${quoteTotal(l)}</strong></div><div class="flow-next"><span>payment status</span><strong>${l.paid?'✓ sample payment verified':l.receiptSubmitted?'◷ receipt submitted, awaiting verification':'◷ awaiting payment verification'}</strong></div><p>${l.paid?'your selected work has activated. the next step is to supply the relevant requirements.':'a receipt is evidence for review. your work activates only after the transaction is verified.'}</p>${l.paid?button('complete my requirements →','client/'+l.id+'/requirements'):l.step1Demo?`<div class="flow-demo-control"><p>experience control · no money is collected</p><button class="secondary" onclick="simulateActivation('${l.id}')">simulate verified payment →</button></div>`:'<p class="small">your team will provide the accepted quotation and approved payment instructions.</p>'}</section><div class="flow-actions">${button('back to selection','client/'+l.id+'/review','ghost')}</div>`+flowEnd(l);
if(p==='requirements')return h+flowTitle('systems / your requirements','let’s prepare your work.','provide only what is needed for the services you selected. the same information is requested once.')+`<div class="flow-requirements">${l.requirements.map(r=>`<article class="flow-requirement"><div class="flow-status ${['accepted','submitted'].includes(r.status)?'success':'pending'}">${['accepted','submitted'].includes(r.status)?'✓':'◷'} ${E(r.status)}</div>${tag(r.venture)}<h3>${E(r.title)}</h3><form onsubmit="flowRequirement(event,'${l.id}','${r.id}')"><label>your response</label><textarea name="answer" required>${E(r.answer)}</textarea><label>sample supporting file, optional</label><input type="file" name="supporting"><div class="flow-actions"><button class="secondary">save requirement</button></div></form></article>`).join('')}</div><div class="flow-note">use sample text and files only. live client uploads will require secure shared storage.</div><div class="flow-actions">${button('view my project →','client/'+l.id+'/progress')}</div>`+flowEnd(l);
let done=l.work.filter(w=>w.status==='delivered').length,completed=l.work.length&&done===l.work.length;return h+flowTitle('success / follow the work',completed?'your stage is complete.':'clear progress, one item at a time.',`${done} of ${l.work.length} services delivered. dates below belong to the agreed scope.`)+`${completed?`<div class="flow-badge"><span>✓</span><div><strong>your agreed scope completed</strong><p>hamzury journey badge · based on the agreed sample scope.</p></div></div>`:''}<div class="flow-nextaction"><span>your next action</span><p>${E(l.next||'your team is preparing the next update.')}</p></div><div class="flow-deliveries">${l.work.map(w=>{let f=l.files.find(f=>f.workId===w.id&&f.release==='final');let state=w.status==='delivered'?'success':['blocked','changes requested'].includes(w.status)?'danger':'pending';return `<article class="flow-delivery"><div class="flow-status ${state}">${state==='success'?'✓':state==='danger'?'!':'◷'} ${E(w.status)}</div>${tag(w.venture)}<h3>${E(w.title)}</h3><p class="small">expected delivery: ${displayDate(w.due)}</p><p>${E(w.evidence||'your responsible team will publish the next update here.')}</p>${f?`<button class="secondary" onclick="downloadFile('${f.id}')">download delivered file</button>`:''}</article>`}).join('')}</div><div class="flow-actions"><button class="secondary" onclick="downloadJourney('${l.id}','pdf','roadmap')">download full roadmap</button><button class="ghost" onclick="downloadJourney('${l.id}','png','roadmap')">save roadmap image</button></div>${l.step1Demo?`<details class="flow-demo-control"><summary>experience controls</summary><p>simulate one delivery to see the green completed state and in-place download.</p><button class="secondary" onclick="simulateDelivery('${l.id}')">simulate next delivery</button></details>`:''}<section class="flow-message"><span class="eyebrow">your next stage</span><h2>${completed?'build on the result.':'keep the next step in view.'}</h2><p>your remaining roadmap stays with you. review the next useful service when the current foundation is ready.</p><button class="secondary" onclick="packageLevel=1;flowGo(lead('${l.id}'),'roadmap')">explore the next stage →</button></section><section class="flow-message"><h2>updates & support</h2>${l.updates.map(u=>`<div class="statusline"><span class="small">${displayDate(u.at)}</span><p>${E(u.message)}</p></div>`).join('')||'<p>your team’s next update will appear here.</p>'}<form onsubmit="feedback(event,'${l.id}')"><label>feedback or something that needs attention</label><textarea name="message" required></textarea><div class="flow-actions"><button class="secondary">send to the team</button></div></form></section>`+flowEnd(l)};
function flowItem(l,s){let c=choice(l,s.id),active=l.work.some(w=>w.serviceId===s.id);return `<article class="flow-item ${c==='have'?'have':''} ${c==='selected'?'selected':''}"><div class="flow-itemtop"><div>${tag(s.v)}<details><summary>${E(s.title)}</summary><p>${E(s.deliver)}</p><p class="small">requirements: ${E(s.req)}</p>${s.dependencies?.length?`<p class="small">${E(s.dependencyReason)}</p>`:''}</details></div><strong>${price(s,l)}</strong></div><p class="flow-benefit">${E(s.scope)}</p><div class="flow-itembottom"><span class="small">◷ ${duration(s)}</span><div class="flow-itemchoices">${active?'<span class="flow-status pending">in active order</span>':`<button class="flow-add ${c==='selected'?'is-added':''}" aria-pressed="${c==='selected'}" aria-label="${c==='selected'?'remove':'add'} ${E(s.title)}" onclick="requestFlowChoice('${l.id}','${s.id}','${c==='selected'?'later':'selected'}')">${c==='selected'?'✓ added':'+ add'}</button><button class="flow-have" aria-pressed="${c==='have'}" onclick="requestFlowChoice('${l.id}','${s.id}','${c==='have'?'later':'have'}')">${c==='have'?'✓ already have · undo':'i already have this'}</button>`}</div></div></article>`}
function requestFlowChoice(id,sid,value){let l=lead(id),s=flowItems(l).find(s=>s.id===sid);if(l.work.some(w=>w.serviceId===sid)){toast('this item is already in your activated order');return}let missing=value==='selected'?(s.dependencies||[]).filter(id=>!['selected','have'].includes(choice(l,id))):[];let dependents=value==='later'?chosen(l).filter(x=>(x.dependencies||[]).includes(sid)):[];if(missing.length||dependents.length){dependencyPrompt={client:id,sid,value,missing,dependents:dependents.map(s=>s.id)};render();return}applyFlowChoice(l,sid,value);render()}
function applyFlowChoice(l,id,value){l.itemChoices=l.itemChoices||{};l.itemChoices[id]=value;l.clientSelected=value==='selected'?[...new Set([...(l.clientSelected||[]),id])]:(l.clientSelected||[]).filter(x=>x!==id);l.quoteAccepted=false;save()}
function dependencyDialog(l){let p=dependencyPrompt,services=flowItems(l);return `<div class="flow-modal-backdrop"><section class="flow-modal" role="dialog" aria-modal="true" aria-labelledby="dependency-title"><h2 id="dependency-title">keep the work connected.</h2>${p.missing.length?`<p>this sample scope also needs:</p><ul>${p.missing.map(id=>`<li>${E(services.find(s=>s.id===id)?.title)}</li>`).join('')}</ul><p class="small">you can add them, or return and mark assets you already have. nothing is added without your choice.</p><button onclick="confirmDependency('${l.id}')">add these items with my selection</button>`:`<p>removing this prerequisite also postpones:</p><ul>${p.dependents.map(id=>`<li>${E(services.find(s=>s.id===id)?.title)}</li>`).join('')}</ul><button onclick="confirmDependency('${l.id}')">postpone these items together</button>`}<button class="secondary" onclick="dependencyPrompt=null;render()">go back</button></section></div>`}
function confirmDependency(id){let l=lead(id),p=dependencyPrompt;if(p.missing.length)p.missing.forEach(id=>applyFlowChoice(l,id,'selected'));if(p.dependents.length)p.dependents.forEach(id=>applyFlowChoice(l,id,'later'));applyFlowChoice(l,p.sid,p.value);dependencyPrompt=null;render()}
function reviewFlow(id){let l=lead(id);if(!chosen(l).length){toast('choose at least one item first');return}flowGo(l,'review')}
function acceptFlowQuote(id){let l=lead(id);if(!chosen(l).length||missingDependencies(l).length)return;if(!l.step1Demo){requestQuote(id);flowGo(l,'payment');return}l.quoteAccepted=true;l.activeSelection=chosen(l).map(s=>s.id);event(l,'sample selection reviewed and accepted');flowGo(l,'payment')}
function simulateActivation(id){let l=lead(id);if(!l.step1Demo||!l.quoteAccepted){toast('review and confirm your selection first');return}let services=flowItems(l).filter(s=>l.activeSelection.includes(s.id));l.paid=true;l.payment={amount:services.reduce((n,s)=>n+Number(s.price),0),ref:'SIMULATED-EXPERIENCE',at:now(),simulation:true};l.stage='onboarding';l.work=services.map(s=>({id:uid('work'),serviceId:s.id,venture:s.v,title:s.title,status:'waiting for requirements',owner:'sample venture operations lead',due:sampleBusinessDate(Number(s.days)),standard:s.deliver,evidence:''}));let groups=[...new Set(services.map(s=>s.v))];l.requirements=groups.map(v=>({id:uid('requirement'),venture:v,title:v==='bizdoc'?'confirm the business details and existing document list':v==='medialy'?'describe your audience and share the existing brand assets':'confirm the business details, tools and preferred contact route',answer:'',status:'needed',due:''}));l.next='complete the requirement checklist so the teams can prepare the work';event(l,'sample payment verified; demo work routed');flowGo(l,'requirements')}
function flowRequirement(e,id,rid){respondRequirement(e,id,rid)}
async function simulateDelivery(id){let l=lead(id);if(!l.step1Demo)return;let w=l.work.find(w=>w.status!=='delivered');if(!w){toast('all sample services are delivered');return}let file=new File(['hamzury holding\nsample delivery\nreference: '+l.id+'\nservice: '+w.title+'\n\nthis is a demonstration delivery index. it is not an official certificate, registered document or final client deliverable.'],w.serviceId+'-sample-delivery.txt',{type:'text/plain'}),fid=uid('delivery'),idb=await filesDB;await new Promise((res,rej)=>{let tx=idb.transaction('files','readwrite');tx.objectStore('files').put(file,fid);tx.oncomplete=res;tx.onerror=rej});w.status='delivered';w.evidence='sample quality review complete. the demonstration delivery index is ready below.';l.files.push({id:fid,name:file.name,title:w.title+' / sample delivery',workId:w.id,release:'final',at:now()});let complete=l.work.every(w=>w.status==='delivered');l.stage=complete?'delivered':'active';l.next=complete?'review your delivered work and consider the next useful stage':'review the delivered item while the remaining work continues';l.updates.unshift({message:'sample delivery available: '+w.title,at:now(),waiting:'you',next:l.next});event(l,'sample item delivered: '+w.title);render()}
async function saveReference(id){let l=lead(id),c=document.createElement('canvas');c.width=1080;c.height=1350;let x=c.getContext('2d');x.fillStyle='#f8f3eb';x.fillRect(0,0,1080,1350);x.fillStyle='#b99770';x.fillRect(0,0,248,10);x.fillStyle='#3b241a';x.fillRect(248,0,832,10);try{let im=new Image();im.src='assets/hamzury.png';await im.decode();x.drawImage(im,85,75,300,300*im.height/im.width)}catch{}x.fillStyle='#3b241a';x.font='18px Arial';x.fillText('your journey. a clear next step.',85,170);x.beginPath();x.arc(135,280,50,0,Math.PI*2);x.fillStyle='#e7edde';x.fill();x.fillStyle='#375c3a';x.font='42px Arial';x.fillText('✓',118,296);x.fillStyle='#3b241a';x.font='52px Arial';x.fillText('you’ve taken the first step.',85,420);x.font='27px Arial';let y=500;['thank you for choosing hamzury.','we have received your answers.','our specialist team will review your situation','and prepare a clear recommendation.'].forEach(t=>{x.fillText(t,85,y);y+=44});x.strokeStyle='#d6c5b0';x.strokeRect(85,760,910,215);x.font='17px Arial';x.fillText('YOUR JOURNEY REFERENCE',120,810);x.font='bold 43px Arial';x.fillText(l.id,120,885);x.font='21px Arial';x.fillText('keep this reference for your next visit.',120,935);x.font='22px Arial';x.fillText('awareness → strategy → structure',85,1130);x.fillText('systems → success',85,1170);x.font='17px Arial';x.fillStyle='#756959';x.fillText('reference only. secure verification protects your live account.',85,1260);c.toBlob(blob=>{downloadBlob(blob,l.id+'-reference.png');toast('your reference card is ready to save')},'image/png')}
const originalCardExport=downloadJourney;
downloadJourney=function(id,type,kind){if(kind==='card'&&type==='png')return saveReference(id);return originalCardExport(id,type,kind)};
const previousGuidedNext=guidedNext;
guidedNext=function(e,fid,id){previousGuidedNext(e,fid,id);let l=lead(id)||db.leads.find(l=>formAnswers._contact&&l.contact?.trim().toLowerCase()===formAnswers._contact.trim().toLowerCase());if(l&&location.hash.includes('/proposal')&&l.proposalVersion?.preliminary)flowGo(l,'reference')};
const previousAccessFlow=access;
access=function(){return previousAccessFlow().replaceAll('HH-JOURNEY-001','HH-FLOW-001')};
const previousClientRender=render;
render=function(){route=location.hash.slice(1).split('/');if(route[0]==='client'){root.innerHTML=demo()+clientView();let v=brandFor();document.documentElement.style.setProperty('--choc',v?.color||'#3b241a');document.documentElement.style.setProperty('--milk',v?'#f6f8fa':'#f8f3eb');attachLabels();drawChat();document.getElementById('chatmount').style.display='none';document.querySelector('.flow-modal button')?.focus()}else{previousClientRender();let chat=document.getElementById('chatmount');if(chat)chat.style.display=''}};
render();

window.addEventListener('keydown',e=>{if(!dependencyPrompt)return;let dialog=document.querySelector('.flow-modal');if(e.key==='Escape'){dependencyPrompt=null;render();return}if(e.key==='Tab'&&dialog){let buttons=[...dialog.querySelectorAll('button')];let first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
